mapper.select:
SELECT used_storage_bytes
FROM org_storage_usage
WHERE org_id = #{orgId}

mapper.update:
UPDATE org_storage_usage
SET used_storage_bytes = used_storage_bytes + #{delta}
WHERE org_id = #{orgId}

UPDATE org_storage_usage
SET used_storage_bytes = GREATEST(0, used_storage_bytes - #{delta})
WHERE org_id = #{orgId}

UPDATE org_storage_usage
SET used_gpu = used_gpu + #{gpuDelta},
    used_cpu = used_cpu + #{cpuDelta},
    used_memory_mb = used_memory_mb + #{memoryMbDelta}
WHERE org_id = #{orgId}
